  const transform=([x,y]: Vec2): Vec2=>[x*sx,y*sy];
  const ring=mapProfiles(measuredProfiles.offsetRing,transform),top=mapProfiles(mountingBores(measuredProfiles.offsetTop,p.holeDiameter),transform);
